package com.nirikshan.controller;
import com.nirikshan.dto.*;import com.nirikshan.dto.AuthResponses.*;import com.nirikshan.model.*;import com.nirikshan.repository.*;import com.nirikshan.security.CurrentUser;import com.nirikshan.service.*;import org.springframework.web.bind.annotation.*;import java.util.*;
@RestController @RequestMapping("/api/security") public class SecurityController {private final CurrentUser current;private final AlertService alerts;private final SecurityInstructionRepository instructions;private final AlertRepository alertRepository;public SecurityController(CurrentUser c,AlertService a,SecurityInstructionRepository i,AlertRepository r){current=c;alerts=a;instructions=i;alertRepository=r;}
 @GetMapping("/alerts") public List<SecurityAlertInfo> alerts(){User u=security();return alertRepository.findByResolvedOrderByTimestampDesc(false).stream().filter(a->a.getZone().getId().equals(u.getAssignedZone().getId())).map(a->new SecurityAlertInfo(a.getId(),a.getZone().getId(),a.getZone().getName(),a.getZone().getLatitude(),a.getZone().getLongitude(),a.getTimestamp(),a.getMessage(),a.getSeverity().name(),a.isResolved())).toList();}
 @PostMapping("/alerts/{id}/acknowledge") public AlertResponse acknowledge(@PathVariable Long id){User u=security();Alert alert=alertRepository.findById(id).orElseThrow(()->new IllegalArgumentException("Alert not found"));if(!alert.getZone().getId().equals(u.getAssignedZone().getId()))throw new IllegalArgumentException("Alert is outside your assigned zone");return alerts.resolve(id);}
 @GetMapping("/instructions") public List<InstructionInfo> instructions(){User u=security();return instructions.relevant(u.getId(),u.getAssignedZone().getId()).stream().map(i->new InstructionInfo(i.getId(),i.getMessage(),i.getTargetZone()==null?null:i.getTargetZone().getId(),i.getTargetSecurityUser()==null?null:i.getTargetSecurityUser().getId(),i.getCreatedAt())).toList();}
 private User security(){User u=current.get();if(u.getRole()!=UserRole.SECURITY||u.getAssignedZone()==null)throw new IllegalArgumentException("No security zone is assigned");return u;}}
